// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 virtualBase,
        uint128 virtualNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoyalties
    ) public {
        // Admissible domain: feeRate must be <= 5000, otherwise the reference
        // legitimately reverts with FeeRateTooHigh and never stores anything.
        feeRate = uint16(bound(feeRate, 0, 5_000));

        C fresh = new C(address(this), address(this), address(this));
        bool ok;
        try fresh.initialize(
            baseToken, nft, virtualBase, virtualNft, changeFee, feeRate,
            merkleRoot, useOracle, payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(
            !ok || fresh.baseToken() == baseToken,
            "initialize must set baseToken to the given _baseToken"
        );
    }
}

