// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        uint56 initialChangeFee,
        uint56 newChangeFee,
        uint128 vBase,
        uint128 vNft,
        uint16 feeRate,
        bool useOracle,
        bool payRoyalties,
        bytes32 merkleRoot
    ) public {
        vm.assume(vNft > 0);
        vm.assume(feeRate <= 5_000);

        // First initialization: succeeds for any admissible input.
        c.initialize(
            address(0),
            address(0),
            vBase,
            vNft,
            initialChangeFee,
            feeRate,
            merkleRoot,
            useOracle,
            payRoyalties
        );

        // Second initialization attempt with a different changeFee must revert
        // and must NOT change changeFee.
        bool reverted;
        try c.initialize(
            address(0),
            address(0),
            vBase,
            vNft,
            newChangeFee,
            feeRate,
            merkleRoot,
            useOracle,
            payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: initialize is one-shot; a rejected re-initialization leaves
        // changeFee exactly as set by the successful first call.
        assertTrue(
            reverted && c.changeFee() == initialChangeFee,
            "re-initialization must not overwrite changeFee"
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 fee1, uint56 fee2, uint128 vb, uint128 vn) public {
        // First initialization with fee1: succeeds on both versions.
        c.initialize(address(0), address(0), vb, vn, fee1, 0, bytes32(0), false, false);

        // A second initialization attempt must be a no-op: it reverts
        // (AlreadyInitialized) and must NOT alter any stored parameter,
        // in particular changeFee.
        try c.initialize(address(0), address(0), vb, vn, fee2, 0, bytes32(0), false, false) {
            // should not happen on either version
        } catch {}

        assertTrue(c.changeFee() == fee1);
    }
}
